R_EARTH = 6371.0


def haversine_km(lat1, lon1, lat2, lon2):
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dp, dl = math.radians(lat2 - lat1), math.radians(lon2 - lon1)
    a = math.sin(dp / 2) ** 2 + math.cos(p1) * math.cos(p2) * math.sin(dl / 2) ** 2
    return 2 * R_EARTH * math.asin(math.sqrt(a))


def simplify_geom(points, tol=0.0001):
    """Douglas-Peucker 折线简化：保留边在底图上的弯曲走向，同时压缩 JSON 体积。
    tol 单位为经纬度（0.0001 度 ≈ 11m @北纬 21 度，足以在 zoom 16+ 仍贴合底图道路），
    返回 [[lat, lon], ...]。"""
    pts = [(float(la), float(lo)) for la, lo in points]
    if len(pts) <= 2:
        return [[round(la, 6), round(lo, 6)] for la, lo in pts]

    def _dps(seq):
        if len(seq) <= 2:
            return seq
        x0, y0 = seq[0]
        x1, y1 = seq[-1]
        dx, dy = x1 - x0, y1 - y0
        norm = (dx * dx + dy * dy) ** 0.5
        best_i, best_d = -1, -1.0
        for i in range(1, len(seq) - 1):
            x, y = seq[i]
            if norm < 1e-12:
                d = ((x - x0) ** 2 + (y - y0) ** 2) ** 0.5
            else:
                d = abs(dy * x - dx * y + x1 * y0 - y1 * x0) / norm
            if d > best_d:
                best_d, best_i = d, i
        if best_d > tol:
            left = _dps(seq[:best_i + 1])
            right = _dps(seq[best_i:])
            return left[:-1] + right
        return [seq[0], seq[-1]]

    out = _dps(pts)
    return [[round(la, 6), round(lo, 6)] for la, lo in out]


class NetworkHandler(osmium.SimpleHandler):
    """流式读取 PBF：收集 bbox 内节点坐标 + 符合条件的道路 way。"""

    def __init__(self, bbox):
        super().__init__()
        self.bbox = bbox
        self.coords = {}          # osm node id -> (lat, lon)
        self.ways = []            # (osm way id, [node ids], tags)
        self._in_bbox = set()     # node 在 bbox 内的标记（避免重复存储）

    def _inside(self, lat, lon):
        b = self.bbox
        return b["lat_min"] <= lat <= b["lat_max"] and b["lon_min"] <= lon <= b["lon_max"]

    def node(self, n):
        if self._inside(n.location.lat, n.location.lon):
            self.coords[n.id] = (n.location.lat, n.location.lon)

    def way(self, w):
        h = w.tags.get("highway")
        if h is None or h.split("_")[0] not in LEVELS:
            return
        node_ids = [n.ref for n in w.nodes]
        self.ways.append((w.id, node_ids, dict(w.tags)))


def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("--bbox", default=None,
                        help="自定义 bbox: lat_min,lat_max,lon_min,lon_max（默认全量走廊 bbox）")
    parser.add_argument("--out", default=OUT, help="输出 JSON 路径")
    args = parser.parse_args()

    if not os.path.exists(PBF):
        print(f"[错误] 未找到 PBF 文件: {PBF}")
        sys.exit(1)

    bbox = BBOX
    if args.bbox:
        parts = [float(x) for x in args.bbox.split(",")]
        bbox = {"lat_min": parts[0], "lat_max": parts[1], "lon_min": parts[2], "lon_max": parts[3]}
        print(f"自定义 bbox: {bbox}")

    print("读取 PBF ...")
    handler = NetworkHandler(bbox)
    handler.apply_file(PBF, locations=False)

    coords, ways = handler.coords, handler.ways
    print(f"  bbox 内节点: {len(coords)}, 候选道路: {len(ways)}")

    # 过滤：way 至少 2 个节点在 coords 中
    valid_ways = []
    for wid, node_ids, tags in ways:
        seq = [n for n in node_ids if n in coords]
        if len(seq) >= 2:
            valid_ways.append((wid, seq, tags))
    ways = valid_ways
    print(f"  有效道路: {len(ways)}")

    # ---- 统计节点度（交叉口识别） ----
    degree = Counter()
    for _, seq, _ in ways:
        for a, b in zip(seq, seq[1:]):
            degree[a] += 1
            degree[b] += 1

    # 锚点城市 -> 最近 OSM 节点（距离阈值 6km，否则该城市不可达则警告）
    anchor_match = {}
    for cid, (cname, clat, clon) in ANCHOR_CITIES.items():
        best_n, best_d = None, 1e9
        for nid, (lat, lon) in coords.items():
            if degree[nid] < 1:
                continue
            d = haversine_km(clat, clon, lat, lon)
            if d < best_d:
                best_d, best_n = d, nid
        if best_d <= 6.0:
            anchor_match[cid] = (best_n, best_d, cname)
            print(f"  锚点 {cid}({cname}) -> OSM 节点 {best_n} 距离 {best_d:.2f}km")
        else:
            print(f"  [警告] 锚点 {cid}({cname}) 最近节点 {best_n} 距离 {best_d:.2f}km，超出阈值")

    # 关键节点 = 交叉口(度!=2) ∪ 锚点命中节点 ∪ way 端点
    # 注：OSM way 常在等级变化/任意点断开，首尾节点往往是普通节点(度=2)。
    # 若不强制为关键节点，way 之间的连接边会被丢弃，导致路网断裂成孤立组件。
    key_nodes = {n for n, d in degree.items() if d != 2}
    for nid, _, _ in anchor_match.values():
        key_nodes.add(nid)
    for _, seq, _ in ways:
        key_nodes.add(seq[0])
        key_nodes.add(seq[-1])

    # OSM 节点 id -> 锚点短 ID（边端点需用锚点 ID，保证与节点定义一致）
    osm_to_anchor = {nid: cid for cid, (nid, _, _) in anchor_match.items()}
    # 锚点命中节点：抽稀时无条件作为断点生成边（市中心密集网格常 <50m，不能过滤掉）
    anchor_nodes = set(osm_to_anchor)

    # ---- 抽稀：沿 way 合并中间节点，生成边（保留几何折线 c，贴合底图真实走向） ----
    edge_by_pair = {}  # (from, to) -> edge dict（多条 way 重叠时取距离较短者）
    for wid, seq, tags in ways:
        htype = tags.get("highway", "primary")
        htype_base = htype.split("_")[0]
        speed, road_type = SPEED.get(htype_base, (60, "primary"))
        wname = tags.get("name", tags.get("ref", ""))
        start = seq[0]
        acc = 0.0
        geom = [coords[start]]   # 当前段经过的坐标序列：起点 + 沿途每个 OSM 节点 → 关键点
        for i in range(len(seq) - 1):
            a, b = seq[i], seq[i + 1]
            lat1, lon1 = coords[a]
            lat2, lon2 = coords[b]
            acc += haversine_km(lat1, lon1, lat2, lon2)
            geom.append(coords[b])   # 收集真实走向（底图上是弯曲的，直线会对不上）
            if b in key_nodes or b == seq[-1]:
                if b != start and (acc >= 0.05 or b in anchor_nodes or b == seq[-1]):
                    geom.append(coords[b])
                    pair = (start, b)
                    eid = f"W{wid}-{start}-{b}"
                    if pair in edge_by_pair:
                        # 保留更短/更高级的边
                        old = edge_by_pair[pair]
                        if acc >= old["distanceKm"]:
                            start, acc = b, 0.0
                            geom = [coords[b]]
                            continue
                    f = osm_to_anchor.get(start, str(start))
                    t = osm_to_anchor.get(b, str(b))
                    edge_by_pair[pair] = {
                        "id": eid, "fromNodeId": f, "toNodeId": t,
                        "distanceKm": round(acc, 2), "speedKmh": speed, "customs": False,
                        "name": wname or f"道路 {wid}", "roadType": road_type,
                        "c": simplify_geom(geom),
                    }
                start, acc = b, 0.0
                geom = [coords[b]]

    # ---- 组装节点 ----
    nodes = []
    used_ids = set()
    name_by_node = {}

    # 锚点城市节点（保留原 ID）
    for cid, (nid, dist, cname) in anchor_match.items():
        lat, lon = coords[nid]
        nodes.append({"id": cid, "name": cname, "latitude": round(lat, 6), "longitude": round(lon, 6)})
        used_ids.add(cid)
        name_by_node[nid] = cname

    # 其余关键节点
    for nid in sorted(key_nodes - set(a[0] for a in anchor_match.values())):
        lat, lon = coords[nid]
        nodes.append({"id": str(nid), "name": name_by_node.get(nid, ""), "latitude": round(lat, 6), "longitude": round(lon, 6)})
        used_ids.add(str(nid))

    # ---- 组装边（保证边两端节点存在） ----
    edges = []
    seen_edge_ids = set()
    anchor_cids = set(osm_to_anchor.values())
    for _, e in edge_by_pair.items():
        f, t = e["fromNodeId"], e["toNodeId"]
        missing = [x for x in (f, t) if x not in used_ids]
        if missing:
            # 锚点相关边：缺失端是普通节点(度=2 way 端点)，补齐为节点保留，否则边被丢弃导致锚点孤立
            if f not in anchor_cids and t not in anchor_cids:
                continue
            for m in missing:
                nid = int(m)
                lat, lon = coords[nid]
                nodes.append({"id": m, "name": name_by_node.get(nid, ""),
                              "latitude": round(lat, 6), "longitude": round(lon, 6)})
                used_ids.add(m)
        if e["id"] in seen_edge_ids:
            continue
        edges.append(e)
        seen_edge_ids.add(e["id"])

    # 中国侧节点 + 边（保持 ID 兼容场景注入/通关配置）
    cn_id_set = {n["id"] for n in CN_NODES}
    nodes = CN_NODES + [n for n in nodes if n["id"] not in cn_id_set]
    edges = CN_EDGES + edges
    # 中国侧虚拟边贴路几何补全（缺 c 才补，保留手工调整）
    for e in edges:
        if e.get("c") is None and e["id"] in CN_ROAD_GEOM:
            e["c"] = CN_ROAD_GEOM[e["id"]]

    # 版本标记（验证执行）
    with open("convert_version.txt", "w", encoding="utf-8") as f:
        f.write(f"key_nodes={len(key_nodes)} nodes={len(nodes)} edges={len(edges)}\n")

    # ---- 输出 ----
    data = {"nodes": nodes, "edges": edges}
    # 备份旧文件
    if os.path.exists(OUT):
        bak = OUT + ".bak"
        with open(OUT, "r", encoding="utf-8") as f:
            old = f.read()
        with open(bak, "w", encoding="utf-8") as f:
            f.write(old)
        print(f"已备份原路网 -> {bak}")

    with open(OUT, "w", encoding="utf-8") as f:
        # 紧凑输出：几何点增多后，indent=2 会让文件体积膨胀数倍
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
    print(f"已写出: {OUT}")
    print(f"  节点: {len(nodes)} (中国侧 {len(CN_NODES)} + OSM {len(nodes) - len(CN_NODES)})")
    print(f"  边:   {len(edges)} (中国侧 {len(CN_EDGES)} + OSM {len(edges) - len(CN_EDGES)})")

    # 校验连通性（锚点是否都可达）
    print("\n锚点可达性（是否出现在边中）:")
    edge_nodes = set()
    for e in edges:
        edge_nodes.add(e["fromNodeId"])
        edge_nodes.add(e["toNodeId"])
    for cid in ANCHOR_CITIES:
        print(f"  {cid}: {'可达' if cid in edge_nodes else '!!! 未接入路网 !!!'}")

    # 诊断：未接入锚点绑定的 OSM 节点及其所在 way（写文件，避免 stdout 丢失）
    debug_lines = []
    for cid, (nid, dist, cname) in anchor_match.items():
        if cid in edge_nodes:
            continue
        debug_lines.append(f"锚点 {cid}({cname}) 绑定 OSM 节点 {nid} 距离 {dist:.2f}km 度={degree[nid]}")
        lat, lon = coords[nid]
        debug_lines.append(f"  坐标 ({lat:.6f}, {lon:.6f}) 所在 way:")
        for wid, seq, tags in ways:
            if nid in seq:
                idx = seq.index(nid)
                debug_lines.append(f"    way {wid} [{tags.get('highway')}] name={tags.get('name','')!r} pos={idx}/{len(seq)-1} "
                                   f"首={seq[0]} 尾={seq[-1]} 前节点={seq[idx-1] if idx>0 else '-'} 后节点={seq[idx+1] if idx<len(seq)-1 else '-'}")
                # 该 way 中距锚点最近的其他关键节点
                nearest = None
                for j, nd in enumerate(seq):
                    if nd == nid or nd not in coords:
                        continue
                    d2 = haversine_km(lat, lon, coords[nd][0], coords[nd][1])
                    if d2 < 0.05 and (nearest is None or d2 < nearest[0]):
                        nearest = (d2, nd, j)
                if nearest:
                    debug_lines.append(f"      最近(<50m)节点 {nearest[1]} pos={nearest[2]} 距离 {nearest[0]*1000:.0f}m")
        debug_lines.append("")
    if debug_lines:
        with open("convert_debug.txt", "w", encoding="utf-8") as f:
            f.write("\n".join(debug_lines))
        print(f"[诊断] 未接入锚点信息 -> convert_debug.txt ({len(debug_lines)} 行)")


if __name__ == "__main__":
    main()
